"""Read-only stop proposal for the old H stack; never issues stop/disable."""
import csv,html,json
from pathlib import Path
from lab210_resume_common import O,activity,save
A=Path('C:/Users/Admin/Documents/pwa-hub-padrao-visual/docs/revisao-visual-unificado/conexoes-banco-20261120')
def build():
 graph=json.loads((A/'routes-enriched.json').read_text(encoding='utf-8'))
 protected=set()
 for server in graph['servers']:
  if not server.get('shadowed_by_earlier_server_ids') and (18446 in server['ports'] or 443 in server['ports']):protected.update(server['route_and_configured_http_dependency_services'])
 metrics={x['service']:x for x in csv.DictReader((A/'services-with-pools.csv').open(encoding='utf-8-sig'))}
 old=['unificado-homolog-mapa-realtime.service','unificado-homolog-mapa.service','unificado-homolog-pcp.service','unificado-homolog-armacao.service','unificado-homolog-qualidade.service','suprimentos-homolog.service','docker:mapa-homolog-postgrest-reader','docker:mapa-homolog-postgrest-writer']
 assert not protected.intersection(old)
 relations=json.loads((O/'old-services-systemd-relations.json').read_text(encoding='utf-8'))
 for item in relations:
  assert not any(item.get(key) for key in ['RequiredBy','RequisiteOf','BoundBy','ConsistsOf','PropagatesStopTo']),item
 snap=activity();save('activity-old-services-proposal.json',snap);rows=[]
 dependencies=graph['runtime_http_dependencies']+graph['configured_http_dependencies_supplement']
 for unit in old:
  callers=[{'service':x['from_service'],'port':x['port'],'path':x['path']} for x in dependencies if unit in x.get('direct_services',[])]
  if unit=='docker:mapa-homolog-postgrest-reader':callers.append({'service':'unificado-homolog-pcp.service','port':13153,'path':'/rest/v1 via internal13153→13151'})
  callers=list({(x['service'],x['port'],x['path']):x for x in callers}.values())
  rows.append({'service':unit,'current_connections':snap['by_service'].get(unit,0),'observed_minimum':metrics[unit]['minimum'],'observed_mean':metrics[unit]['mean_time_weighted'],'observed_maximum':metrics[unit]['maximum'],'protected_18446_or_production_caller':False,'configured_callers':callers,'evidence':'No loaded18446/443 route or configured HTTP dependency reaches this service; Nginx and all inventoried units/env hashes rechecked after pool changes','scope_note':'Stopping this service can affect the old H stack; it does not authorize stopping its database','stop_applied':False})
 result={'services':rows,'systemd_reverse_stop_dependencies_empty':True,'current_connections_releasable':sum(r['current_connections'] for r in rows),'protected_services_excluded':['unificado-homolog-hub.service','unificado-homolog-tv.service','carta-traco-staging.service','laboratorio-homolog.service','pcp-unificado-test.service'],'databases_must_be_kept':['mapa_unificado_homolog_20261016'],'evidence_limit':'Shared Nginx combined logs lack destination host/port. Old stack real human inactivity cannot be proved from that log; old service journals show traffic. This is dependency isolation from18446/production, not proof the old stack is unused.','applied':False}
 save('old-services-proposal.json',result)
 e=lambda x:html.escape(str(x))
 body='<h1>Homologação antiga16/10 · proposta de parada</h1><p><strong>SOMENTE LEITURA · NENHUM STOP/DISABLE APLICADO</strong></p><p>Os serviços abaixo ficam fora das rotas carregadas da18446 e dos vhosts de produção e das dependências HTTP configuradas inventariadas. A conferência de integridade após os pools confirmou os350 arquivos/211 configurações de produção e todas as unidades/env inventariadas. Podem compor uma parada coordenada da pilha antiga, após decisão do usuário. Não há autorização para aplicar esta proposta.</p><table><tr><th>Serviço/contêiner</th><th>Libera agora</th><th>Mín./média/máx. na hora útil</th><th>Quem depende hoje</th></tr>'
 for row in rows:
  body+='<tr><td>'+e(row['service'])+'</td><td>'+e(row['current_connections'])+'</td><td>'+e('/'.join(str(row[k]) for k in ['observed_minimum','observed_mean','observed_maximum']))+'</td><td>'+e('; '.join(x['service']+' :'+str(x['port'])+' '+x['path'] for x in row['configured_callers']) or 'Nenhum chamador de produção/18446 identificado; somente contexto antigo')+'</td></tr>'
 body+='</table><p>Liberação instantânea estimada: <strong>'+e(result['current_connections_releasable'])+'</strong> conexões. Varia com uso e tarefas; não soma ganhos de banco e serviço duas vezes. O banco continua ligado.</p><p>As seis unidades systemd também não têm RequiredBy, RequisiteOf, BoundBy, ConsistsOf ou PropagatesStopTo: <a href="old-services-systemd-relations.json">relações reais</a>. Portanto não foi identificada cascata de parada sobre produção/18446.</p><h2>Ordem proposta e rollback</h2><p>Parar primeiro os timers unificado-homolog-tarefas-* (ged, notify, outbox, suprimentos), aguardando as execuções em curso concluírem naturalmente; depois o realtime/Mapa antigo, PCP/Armação/Qualidade antigos, Suprimentos antigo e seus PostgRESTs. Os jobs não mantêm conexões fora da execução, portanto o ganho instantâneo deles é0 e a redução é de picos futuros. Stop de uma unidade oneshot sem parar seu timer não impede a próxima execução. Não usar kill/pg_terminate_backend, disable ou apagar banco/arquivo. Rollback: start dos mesmos serviços/contêineres e timers, em ordem inversa, com gate18446 e contagens após cada etapa. Sem disable: revisar novamente após reboot/restart do Docker, pois serviços habilitados e políticas de restart podem fazê-los voltar.</p><h2>Exclusões obrigatórias</h2><ul><li>unificado-homolog-hub e unificado-homolog-tv atendem a18446: manter.</li><li>carta-traco-staging, laboratorio-homolog e pcp-unificado-test atendem produção: manter.</li><li>mapa_unificado_homolog_20261016 é usado pela Carta de produção: manter banco, role, arquivos e conexões de produção.</li><li>suprimentos-nf-worker não entra na lista confirmada: revisar diretórios/filas compartilhados antes de qualquer proposta de parada; ganho observado de conexão persistente0.</li><li>concretrack-staging-* é outro ambiente, fora desta lista16/10; nenhuma parada autorizada.</li></ul><h2>Limite da evidência</h2><p>'+e(result['evidence_limit'])+'</p><p>O journal antigo tem177 chamadas de Armação,406 de PCP,3 de Qualidade e23525 de Suprimentos nos7 dias avaliados na Parte A. A ausência de usuário humano não foi provada; uma parada pode afetar usuários da homologação antiga. Não há rota identificada desses serviços para18446/produção. Registros completos em <a href="old-services-proposal.json">JSON</a>, <a href="production-audit-after-pools.json">auditoria de integridade</a> e <a href="activity-old-services-proposal.json">conexões por PID/cgroup</a>.</p>'
 page='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proposta de parada16/10</title><style>body{font:15px/1.55 system-ui;color:#193744;background:#f4f7fa;margin:24px;overflow-wrap:anywhere}main{max-width:1250px;margin:auto}table{border-collapse:collapse;width:100%;background:white;font-size:13px}td,th{border:1px solid #ccd8e2;padding:10px;text-align:left;vertical-align:top}th{background:#e6eff6}@media(max-width:700px){body{margin:12px}table{display:block;overflow:auto}}</style><main>'+body+'</main></html>'
 (O/'SERVICOS_ANTIGOS_PROPOSTA.html').write_text(page,encoding='utf-8');print(json.dumps({'services':len(rows),'connections_now':result['current_connections_releasable'],'applied':False}))
if __name__=='__main__':build()
